  verifier(proche(f.q2, 1 - press / sct, 1e-9) && f.q2 < f.r2 && f.r2a < f.r2, "R² validé : identique au recalage point par point (un point retiré à la fois)");
  // la personne corrige la proposition des règles, puis valide
